#include "net_conntrack.h"
static int eq(const struct net_flow*a,const struct net_flow*b){return a->source==b->source&&a->destination==b->destination&&a->source_port==b->source_port&&a->destination_port==b->destination_port&&a->protocol==b->protocol;}
static int reverse(const struct net_flow*a,const struct net_flow*b){return a->source==b->destination&&a->destination==b->source&&a->source_port==b->destination_port&&a->destination_port==b->source_port&&a->protocol==b->protocol;}
void net_conntrack_expire(struct net_conntrack*t,uint32_t now){if(!t)return;for(uint32_t i=0;i<NET_CONNTRACK_CAPACITY;i++)if(t->entries[i].active&&(int32_t)(now-t->entries[i].expires)>=0)t->entries[i].active=0;}
int net_conntrack_observe(struct net_conntrack*t,const struct net_flow*f,uint32_t now,uint32_t life){if(!t||!f||!life||life>=0x80000000U)return -1;net_conntrack_expire(t,now);for(uint32_t i=0;i<NET_CONNTRACK_CAPACITY;i++)if(t->entries[i].active){struct net_flow_entry*e=&t->entries[i];if(eq(&e->flow,f)){e->expires=now+life;return e->seen_reverse?1:0;}if(reverse(&e->flow,f)){e->seen_reverse=1;e->expires=now+life;return 1;}}uint32_t slot=NET_CONNTRACK_CAPACITY;for(uint32_t i=0;i<NET_CONNTRACK_CAPACITY;i++)if(!t->entries[i].active){slot=i;break;}if(slot==NET_CONNTRACK_CAPACITY){slot=0;for(uint32_t i=1;i<NET_CONNTRACK_CAPACITY;i++)if((int32_t)(t->entries[i].expires-t->entries[slot].expires)<0)slot=i;t->evictions++;}struct net_flow_entry*e=&t->entries[slot];e->flow=*f;e->expires=now+life;e->active=1;e->seen_reverse=0;t->inserts++;return 0;}
